import { createSlice } from '@reduxjs/toolkit';
const initialState = {};
export const getPreloadedState = async ({
  types,
  data
}) => {
  return initialState;
};
export const uiStateSlice = createSlice({
  name: 'ui',
  initialState,
  reducers: {
    setState(state, action) {
      return action.payload;
    },
    updateState(state, action) {
      state = {
        ...state,
        ...action.payload
      };
    }
  }
});

// Exposing the state functions as generics
export const setState = uiStateSlice.actions.setState;
export const updateState = uiStateSlice.actions.updateState;
export const {
  reducer
} = uiStateSlice;