import { isNestedField, propFilter } from '../../../../../../data/common';
const filterByType = propFilter('type');
export const getAvailableFields = (fields, filterFieldTypes = '*') => {
  const filteredFields = fields.filter(field => {
    if (!field.aggregatable || isNestedField(field)) {
      return false;
    }
    return filterByType([field], filterFieldTypes).length !== 0;
  });
  return filteredFields;
};