export const getValueAxes = yAxes => yAxes.map((y, index) => ({
  id: `ValueAxis-${index + 1}`,
  labels: {
    show: true
  },
  name: `ValueAxis-${index + 1}`,
  position: 'left',
  scale: {
    type: 'linear',
    mode: 'normal'
  },
  show: true,
  style: {},
  title: {
    text: y.label
  },
  type: 'value'
}));