import { i18n } from '@osd/i18n';
import { findLast } from 'lodash';
import { BUCKET_TYPES } from '../../../../../data/common';
import { search } from '../../../../../data/public';
/**
 * Validate if the aggregations to perform are possible
 * @param aggs Aggregations to be performed
 * @param schemas Optional. All available schemas
 * @returns ValidationResult
 */
export const validateAggregations = (aggs, schemas) => {
  // Pipeline aggs should have a valid bucket agg
  const metricAggs = aggs.filter(agg => agg.schema === 'metric');
  const lastParentPipelineAgg = findLast(metricAggs, ({
    type
  }) => type.subtype === search.aggs.parentPipelineType);
  const lastBucket = findLast(aggs, agg => agg.type.type === 'buckets');
  if (!lastBucket && lastParentPipelineAgg) {
    return {
      valid: false,
      errorMsg: i18n.translate('visBuilder.aggregation.mustHaveBucketErrorMessage', {
        defaultMessage: 'Add a bucket with "Date Histogram" or "Histogram" aggregation.',
        description: 'Date Histogram and Histogram should not be translated'
      })
    };
  }

  // Last bucket in a Pipeline aggs should be either a date histogram or histogram
  if (lastBucket && lastParentPipelineAgg && ![BUCKET_TYPES.DATE_HISTOGRAM, BUCKET_TYPES.HISTOGRAM].includes(lastBucket.type.name)) {
    return {
      valid: false,
      errorMsg: i18n.translate('visBuilder.aggregation.wrongLastBucketTypeErrorMessage', {
        defaultMessage: 'Last bucket aggregation must be "Date Histogram" or "Histogram" when using "{type}" metric aggregation.',
        values: {
          type: lastParentPipelineAgg.type.title
        },
        description: 'Date Histogram and Histogram should not be translated'
      })
    };
  }
  const splitSchema = schemas === null || schemas === void 0 ? void 0 : schemas.find(s => s.name === 'split');
  if (splitSchema !== null && splitSchema !== void 0 && splitSchema.mustBeFirst) {
    const firstGroupSchemaIndex = aggs.findIndex(item => item.schema === 'group');
    if (firstGroupSchemaIndex !== -1) {
      return {
        valid: false,
        errorMsg: i18n.translate('visBuilder.aggregation.splitChartOrderErrorMessage', {
          defaultMessage: 'Split chart must be first in the configuration.'
        })
      };
    }
  }
  return {
    valid: true
  };
};