import { getPreloadedState } from './preload';
export const loadReduxState = async services => {
  try {
    const serializedState = services.osdUrlStateStorage.get('_a');
    if (serializedState !== null) return serializedState;
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error(err);
  }
  return await getPreloadedState(services);
};
export const persistReduxState = ({
  style,
  visualization,
  metadata,
  ui
}, services) => {
  try {
    services.osdUrlStateStorage.set('_a', {
      style,
      visualization,
      metadata,
      ui
    }, {
      replace: true
    });
  } catch (err) {
    return;
  }
};