import { createMetricConfig } from './metric';
import { createTableConfig } from './table';
import { createHistogramConfig, createLineConfig, createAreaConfig, createPieConfig } from './vislib';
export function registerDefaultTypes(typeServiceSetup, useVega) {
  const visualizationTypes = [createHistogramConfig, createLineConfig, createAreaConfig, createMetricConfig, createTableConfig];
  if (useVega) visualizationTypes.push(createPieConfig);
  visualizationTypes.forEach(createTypeConfig => {
    typeServiceSetup.createVisualizationType(createTypeConfig());
  });
}